import { spawnSync } from "node:child_process";

// Bridges OpenCode's plugin hooks to `lonca hook`, which reads them with the
// [opencode] profile. A failure blocks the tool call.
export default {
  id: "lonca",
  async setup(ctx) {
    const directory = ctx.location.directory;
    const hook = (event) => {
      const r = spawnSync("lonca", ["hook", "--harness", "opencode"], {
        cwd: directory,
        input: JSON.stringify({ ...event, cwd: directory }),
        encoding: "utf8",
      });
      if (r.error) throw new Error(`lonca hook: ${r.error.message}`);
      if (r.status !== 0) throw new Error(r.stderr || `lonca hook exited ${r.status}`);
      const out = r.stdout.trim();
      const answer = out ? JSON.parse(out) : {};
      if (answer.deny) throw new Error(answer.deny);
    };
    const started = new Set();
    await ctx.tool.hook("execute.before", (event) => {
      if (!started.has(event.sessionID)) {
        started.add(event.sessionID);
        hook({ hook_event_name: "session_start", session_id: event.sessionID });
      }
      hook({ hook_event_name: "before_tool", tool_name: event.tool, tool_input: event.input, session_id: event.sessionID });
    });
    await ctx.tool.hook("execute.after", (event) => {
      hook({ hook_event_name: "after_tool", tool_name: event.tool, tool_input: event.input, session_id: event.sessionID });
    });
    // OpenCode has no stop hook to answer, so a turn that ended is prompted.
    // Not one a person interrupted or one that failed. Only a session that
    // used a tool can hold work, and a failure ends the turn.
    const stopped = (sessionID) => {
      const r = spawnSync("lonca", ["hook", "--harness", "opencode", "--fail-open"], {
        cwd: directory,
        input: JSON.stringify({ hook_event_name: "stop", session_id: sessionID, cwd: directory }),
        encoding: "utf8",
      });
      const out = (r.stdout ?? "").trim();
      return out ? JSON.parse(out).resume : undefined;
    };
    (async () => {
      for await (const event of ctx.event.subscribe({ types: ["session.execution.succeeded"] })) {
        const sessionID = event.data.sessionID;
        const text = started.has(sessionID) ? stopped(sessionID) : undefined;
        if (text) await ctx.session.prompt({ sessionID, text });
      }
    })().catch((e) => console.error(`lonca: ${e}`));
  },
};
